"""Référentiel éditorial d'Arélia. Ne pas confondre 'canon' et 'provisoire'."""
ARTICLES = [
 dict(slug='arelia',title='Empire d’Arélia',category='Empire',status='Établi',summary='Présentation générale du pays, de sa population, de son territoire et de ses grands équilibres.',intro='Arélia est un pays insulaire fictif organisé sous la forme d’un Empire constitutionnel. Son immense territoire rassemble des métropoles littorales, une vallée agricole, des massifs glaciaires et de vastes espaces naturels.',facts={'Population':'100 000 000 habitants','Superficie':'1 000 000 km²','Capitale':'Vésone','Régime':'Empire constitutionnel'},sections=[('Portrait général','L’île forme un territoire continu entouré d’archipels, de baies et de péninsules. Son littoral découpé alterne entre grandes installations portuaires, côtes rocheuses, plages et zones humides.','La géographie est le principal moteur de l’organisation humaine : les montagnes du nord alimentent un système fluvial qui traverse la vallée centrale avant d’atteindre Occidian, à l’ouest.'),('Diversité des paysages','Au nord, les glaciers d’Eldan et le désert de glace d’Yrmoth contrastent avec les forêts tempérées de piémont. Plus au sud, une forêt tropicale humide occupe une partie du centre-est, tandis que le désert de Solmar et le volcan d’Azran dominent le sud-ouest.'),('Institutions','L’organisation politique est celle d’un Empire constitutionnel. L’équilibre précis des pouvoirs entre la Couronne, les institutions représentatives et le gouvernement demeure à définir dans le canon de l’univers.')],related=['vesone','empire-constitutionnel','reseau-hydrographique']),
 dict(slug='vesone',title='Vésone',category='Villes',status='Établi',summary='La capitale impériale, ses canaux, ses ponts et sa fonction institutionnelle.',intro='Vésone est la capitale de l’Empire d’Arélia. Implantée dans la partie centre-orientale du territoire, cette grande cité se distingue par une trame de canaux, de quais et de ponts, évoquant les villes d’eau européennes.',facts={'Statut':'Capitale impériale','Localisation':'Centre-est','Caractère':'Ville de canaux','Population municipale':'Non fixée'},sections=[('Morphologie urbaine','Le centre de Vésone s’organise autour d’îles urbaines, de bras d’eau, d’esplanades et de quartiers reliés par des passerelles. L’eau est à la fois un élément patrimonial, un espace public et une infrastructure de déplacement.'),('Rôle institutionnel','La capitale accueille les principales institutions de l’Empire constitutionnel. Les modalités exactes de leur fonctionnement, les noms des palais et des bâtiments publics sont encore en cours de création.'),('Vie métropolitaine','Les espaces historiques peuvent coexister avec des quartiers contemporains, des transports collectifs et des infrastructures métropolitaines. Cette articulation constitue un axe de développement du monde ouvert.')],related=['arelia','empire-constitutionnel','estrel']),
 dict(slug='occidian',title='Occidian',category='Villes',status='Établi',summary='La métropole du littoral ouest, bâtie à l’embouchure du fleuve central.',intro='Occidian est une grande métropole du littoral occidental et le débouché maritime du réseau hydrographique central. Les eaux issues des montagnes du Nord parcourent l’intérieur de l’île avant de rejoindre l’océan à ses quais.',facts={'Type':'Métropole portuaire','Localisation':'Côte occidentale','Hydrographie':'Embouchure du grand fleuve'},sections=[('Un port d’estuaire','La ville se développe autour des rives du fleuve, de ses bassins et de ses terminaux maritimes. L’estuaire structure ses quartiers, ses franchissements et sa relation commerciale avec le reste de l’île.'),('Liaison avec l’intérieur','La vallée centrale conduit vers Occidian les grands corridors de transport. Ce rôle d’interface peut justifier la présence de chantiers navals, de zones industrielles, de quartiers d’affaires et de réseaux multimodaux.'),('Architecture et identité','L’aspect exact des quartiers, l’histoire du port et la démographie de la ville sont laissés ouverts pour les futures étapes de conception.')],related=['reseau-hydrographique','estrel','orientale']),
 dict(slug='orientale',title='Orientale',category='Villes',status='Établi',summary='Grande métropole méridionale à la limite du désert et de l’océan.',intro='La métropole Orientale occupe le littoral du sud, dans le prolongement des paysages arides de Solmar. Elle constitue un centre urbain majeur à la rencontre du désert, des routes terrestres et des voies maritimes.',facts={'Type':'Métropole portuaire','Localisation':'Côte sud','Milieux voisins':'Désert de Solmar, littoral'},sections=[('Une ville à la lisière du désert','Le tissu urbain s’étend entre la côte et les premières régions sèches. La gestion de l’eau, les paysages minéraux et l’architecture climatique sont des éléments potentiellement structurants de son identité.'),('Un pôle de connexion','Le grand port ouvre la métropole sur l’océan. Les routes et les voies ferrées la relient aux bassins de population de l’intérieur de l’île.'),('Éléments à préciser','Le statut administratif, la population municipale, les quartiers emblématiques et le profil économique exact demeurent provisoires.')],related=['desert-solmar','volcan-azran','occidian']),
 dict(slug='katoru',title='Katoru',category='Villes',status='Établi',summary='Métropole nordique à proximité des glaciers et des archipels septentrionaux.',intro='Katoru est la principale grande métropole du Nord. Elle forme un avant-poste urbain entre les eaux froides, les îles périphériques et les chaînes montagneuses enneigées.',facts={'Type':'Métropole nordique','Localisation':'Nord de l’île','Environnement':'Montagnes, mer froide, glaces'},sections=[('Une ville du Nord','Le relief et les conditions météorologiques y composent un environnement très différent de celui des métropoles du Sud. L’accès au littoral offre des possibilités de ports adaptés aux conditions froides.'),('Paysages environnants','À proximité se rencontrent fjords, vallées encaissées, glaciers et zones polaires. Des icebergs peuvent apparaître au large, dans les secteurs où les glaces rejoignent la mer.'),('Développement futur','Les caractéristiques de la ville — économie, architecture, énergie, organisation politique locale — sont encore à élaborer.')],related=['massif-nord','lac-orelys','arelia']),
 dict(slug='estrel',title='Estrel',category='Villes',status='Établi',summary='Ville centrale de l’axe fluvial et agricole, charnière entre les métropoles.',intro='Estrel est une ville intérieure installée au cœur de la vallée centrale d’Arélia. Elle s’inscrit dans l’axe du fleuve reliant les montagnes du Nord à Occidian.',facts={'Type':'Ville centrale','Localisation':'Vallée centrale','Milieu':'Plaine fluviale'},sections=[('Carrefour géographique','La ville occupe une position privilégiée entre les terres agricoles, le réseau fluvial et les grandes routes nationales. Elle constitue une étape naturelle entre les régions de l’intérieur et le littoral occidental.'),('Paysage urbain','Une silhouette dense de centre-ville peut y côtoyer des espaces agricoles et des quartiers bâtis sur les terrasses de la vallée.'),('Données en préparation','Les contours de l’agglomération, son histoire et sa spécialisation économique ne sont pas encore définitivement établis.')],related=['reseau-hydrographique','occidian','vesone']),
 dict(slug='massif-nord',title='Massif du Nord',category='Géographie',status='Établi',summary='L’épine dorsale glaciaire d’Arélia, origine des principaux cours d’eau.',intro='La grande chaîne montagneuse du Nord impose sa silhouette à une partie importante du territoire. Ses hauts sommets alimentent les glaciers, les lacs et les fleuves qui descendent vers les plaines.',facts={'Type':'Massif montagneux','Position':'Nord','Milieux':'Haute montagne, glaciers'},sections=[('Relief','La chaîne associe aiguilles rocheuses, hauts plateaux, vallées glaciaires et piémonts boisés. Le profil des montagnes doit rester cohérent avec les bassins versants de la carte.'),('Glaciers d’Eldan','La zone glaciaire d’Eldan fournit une partie des eaux de fonte du système hydrographique. Au-delà des glaciers d’altitude, les espaces polaires d’Yrmoth occupent une zone nettement plus limitée.'),('Vie et infrastructures','Les cols, tunnels, vallées et lignes ferroviaires constituent des contraintes fortes pour l’aménagement des territoires septentrionaux.')],related=['lac-orelys','reseau-hydrographique','katoru']),
 dict(slug='lac-orelys',title='Lac d’Orélys',category='Géographie',status='Établi',summary='Lac de piémont alimenté par les eaux des montagnes et des glaciers.',intro='Le lac d’Orélys se trouve en aval des massifs septentrionaux. Il recueille les eaux d’altitude et forme l’un des grands paysages intérieurs d’Arélia.',facts={'Type':'Lac de montagne','Localisation':'Piémont du Nord','Origine':'Bassin glaciaire et hydrologique'},sections=[('Un paysage de transition','Le lac occupe une cuvette bordée de versants montagneux, de forêts et de plateaux. Sa surface a été volontairement réduite lors de la conception cartographique pour rester proportionnée au territoire.'),('Rôle hydrographique','Les torrents descendent des glaciers, alimentent des cours d’eau et rejoignent le système fluvial central. Les modalités précises de connexion avec le lac restent à préciser dans une carte topographique technique.'),('Usages futurs','Le lac pourrait accueillir des villages, une activité de navigation, des réserves naturelles et des installations hydrauliques, sous réserve des choix de canon à venir.')],related=['massif-nord','reseau-hydrographique','arelia']),
 dict(slug='reseau-hydrographique',title='Réseau hydrographique',category='Géographie',status='Établi',summary='Des sources glaciaires du Nord jusqu’à l’embouchure occidentale, à Occidian.',intro='Le principal système fluvial d’Arélia prend naissance dans les montagnes du Nord, traverse la vallée centrale et se jette dans l’océan au niveau d’Occidian.',facts={'Source':'Massif du Nord','Parcours':'Vallée centrale','Embouchure':'Occidian'},sections=[('Naissance en montagne','La fonte des neiges, les glaciers et les pluies d’altitude alimentent des torrents qui convergent progressivement vers les premières vallées. Le lac d’Orélys appartient à ce grand ensemble hydrographique.'),('Le cours central','Le fleuve traverse les basses terres et la région d’Estrel. Son tracé doit tenir compte du relief réel, des affluents, des méandres et des plaines inondables.'),('L’estuaire d’Occidian','Le réseau aboutit sur la côte occidentale, où l’estuaire sert d’interface entre navigation intérieure, ports maritimes et ville dense.'),('Canaux de Vésone','Le réseau de canaux de la capitale appartient à un ensemble urbain distinct dont les connexions hydrologiques exactes restent à préciser.')],related=['occidian','estrel','lac-orelys']),
 dict(slug='foret-arelia',title='Forêt d’Arélia',category='Nature',status='Établi',summary='Vaste forêt tropicale humide occupant une partie du centre-est de l’île.',intro='La forêt d’Arélia est une région de forêt tropicale humide inspirée des grands bassins équatoriaux. Elle forme une mosaïque de canopées, de rivières, de marécages et de vallées boisées.',facts={'Biome':'Forêt tropicale humide','Position':'Centre-est / Est','Milieux':'Forêts, rivières, zones humides'},sections=[('Structure écologique','La forêt ne se résume pas à un massif végétal uniforme : ses reliefs, la pluviométrie et les réseaux d’eau créent des habitats variés.'),('Rapports aux villes','Elle borde certaines régions urbanisées mais conserve des zones continues. L’aménagement du littoral oriental et les infrastructures doivent préserver des corridors écologiques crédibles.'),('Dans le futur monde ouvert','La région pourra être construite par génération procédurale, avec une densité végétale variable, des cours d’eau navigables et de nombreuses micro-régions.')],related=['littoral-est','arelia','reseau-hydrographique']),
 dict(slug='desert-solmar',title='Désert de Solmar',category='Nature',status='Établi',summary='Désert de sable au sud-ouest, entourant le volcan d’Azran.',intro='Le désert de Solmar occupe une partie du sud-ouest d’Arélia. Après plusieurs révisions de la carte, il est devenu plus compact et sa zone sableuse enveloppe directement le volcan d’Azran.',facts={'Biome':'Désert chaud','Position':'Sud-ouest','Relief associé':'Volcan d’Azran'},sections=[('Sables et reliefs','Les dunes alternent avec des zones rocheuses, des plateaux et des champs de lave. La transition vers les terres habitées doit rester progressive.'),('Contraste climatique','Le désert se distingue fortement de la forêt tropicale humide voisine. La carte future devra expliquer cette répartition par les vents dominants, les reliefs et les régimes de précipitation.'),('Implantations humaines','Les villes littorales voisines sont reliées aux marges du désert, mais les implantations exactes et leurs ressources restent à définir.')],related=['volcan-azran','orientale','arelia']),
 dict(slug='volcan-azran',title='Volcan d’Azran',category='Nature',status='Établi',summary='Volcan actif situé dans le paysage désertique du sud-ouest.',intro='Azran est le principal volcan représenté sur la carte d’Arélia. Son cône s’élève dans l’environnement aride du désert de Solmar, loin des grandes zones forestières.',facts={'Type':'Volcan actif','Localisation':'Sud-ouest','Milieu':'Désert de Solmar'},sections=[('Un relief majeur','Le volcan constitue un point de repère isolé. Son environnement immédiat mêle sables, roches sombres, dépôts volcaniques et champs de lave.'),('Un paysage vivant','Les phénomènes volcaniques peuvent donner lieu à des zones réglementées, des observatoires scientifiques et des itinéraires d’exploration. Leur organisation reste provisoire.'),('Échelle et réalisme','La carte illustrée n’est pas une carte géologique : les distances, pentes et risques devront être reconstruits pour le jeu et les futures cartes techniques.')],related=['desert-solmar','orientale','massif-nord']),
 dict(slug='littoral-est',title='Littoral oriental',category='Géographie',status='Établi',summary='La façade maritime à l’est de la forêt, entre criques, ports et archipels.',intro='La côte orientale d’Arélia longe le grand massif forestier et se prolonge par des baies, des îles et des zones urbaines littorales. Son implantation a été pensée au-delà de la forêt, vers l’océan.',facts={'Position':'Façade est','Milieux':'Baies, plages, ports, archipels'},sections=[('Un trait de côte découpé','Le littoral associe des péninsules, des embouchures et de petits archipels. La carte définit une intention géographique, sans établir encore chaque baie et chaque cap.'),('Entre nature et urbanisation','Des agglomérations secondaires pourraient être implantées sur les côtes aménagées, tandis que d’autres secteurs resteraient moins accessibles pour préserver les écosystèmes.'),('Réseaux maritimes','Les grandes routes maritimes et les ports de la côte orientale compléteraient le réseau occidental et méridional.')],related=['foret-arelia','vesone','arelia']),
 dict(slug='empire-constitutionnel',title='Empire constitutionnel',category='Institutions',status='Établi',summary='Cadre politique de l’Empire d’Arélia et principes constitutionnels encore à définir.',intro='Arélia est un Empire constitutionnel : l’institution impériale coexiste avec un ordre juridique constitutionnel. Les compétences exactes de l’empereur, du gouvernement et des organes représentatifs ne sont pas encore arrêtées.',facts={'Forme de l’État':'Empire constitutionnel','Capitale':'Vésone','Dynastie':'À définir','Constitution':'À rédiger'},sections=[('Un cadre fondateur','Le choix du régime est établi, mais ne permet pas à lui seul de déduire si le souverain exerce un pouvoir exécutif, essentiellement symbolique ou partagé. Ce point devra être explicitement fixé.'),('Les institutions à imaginer','L’architecture institutionnelle devra préciser la représentation politique, la séparation des pouvoirs, la justice, les collectivités et les mécanismes de révision constitutionnelle.'),('Place dans le récit','Un régime constitutionnel offre de nombreuses possibilités narratives autour de la légitimité, des équilibres politiques, des transformations sociales et des rapports entre les régions.')],related=['arelia','vesone','chronologie']),
 dict(slug='chronologie',title='Chronologie d’Arélia',category='Histoire',status='En conception',summary='Les grandes périodes de l’histoire impériale, à construire sans anticiper le canon.',intro='La chronologie officielle de l’Empire d’Arélia n’a pas encore été définie. Cet article sert de point d’entrée pour les futures périodes, dynasties, crises, réformes et découvertes de l’univers.',facts={'Période fondatrice':'À définir','Ère contemporaine':'À définir','Première constitution':'À définir'},sections=[('Établir les périodes','La chronologie pourra distinguer les peuplements anciens, les formations politiques régionales, l’unification, les phases constitutionnelles et l’époque contemporaine.'),('Documenter les sources','Chaque date, événement et personnage devra renvoyer vers une source narrative ou un document de référence. Les affirmations contradictoires pourront être présentées comme des interprétations de l’histoire.'),('Statut actuel','Aucune date de fondation, aucun monarque historique et aucun conflit majeur ne sont considérés comme établis à ce stade.')],related=['arelia','empire-constitutionnel','vesone']),
 dict(slug='administration',title='Organisation territoriale',category='Institutions',status='En conception',summary='Étude des régions, provinces et collectivités de l’Empire.',intro='L’Empire d’Arélia compte plusieurs grands ensembles géographiques et urbains, mais ses subdivisions administratives ne sont pas encore fixées.',facts={'Régions officielles':'Non définies','Collectivités locales':'Non définies'},sections=[('Une organisation à concevoir','Le découpage administratif devra trouver un équilibre entre la géographie naturelle, les bassins de population et l’histoire politique.'),('Rôle des métropoles','Vésone, Occidian, Orientale, Katoru et Estrel pourraient constituer des centres administratifs majeurs, sans que cela implique encore un statut particulier.'),('Documents à produire','Une carte des provinces, une nomenclature territoriale et une répartition cohérente des compétences restent à rédiger.')],related=['empire-constitutionnel','arelia','vesone']),
 dict(slug='transports',title='Réseaux de transport',category='Société',status='En conception',summary='Une vision des routes, chemins de fer, ports et corridors entre les régions.',intro='Les grandes villes d’Arélia sont reliées par des corridors terrestres et maritimes. Le réseau détaillé doit encore être dimensionné pour une île d’un million de kilomètres carrés.',facts={'Axes structurants':'Intermétropolitains','Transport fluvial':'Axe central vers Occidian','Réseau ferroviaire':'À concevoir'},sections=[('Connexions interurbaines','Le réseau devra franchir les piémonts du Nord, desservir la vallée centrale et contourner les environnements naturels fragiles.'),('Ports et voies d’eau','Occidian est le débouché principal du fleuve central. Vésone dispose également de canaux urbains, tandis qu’Orientale et Katoru s’inscrivent dans les réseaux maritimes.'),('Projection vers le jeu','Ces corridors fourniront la structure de déplacement du futur open-world, avant l’ajout de quartiers, échangeurs, gares et voies secondaires.')],related=['occidian','orientale','reseau-hydrographique']),
 dict(slug='yrmoth',title='Désert de glace d’Yrmoth',category='Nature',status='Établi',summary='Une zone polaire réduite dans l’extrême Nord, bordée de reliefs et d’eaux froides.',intro='Yrmoth désigne le désert de glace situé à l’extrême Nord d’Arélia. Son emprise a été volontairement réduite pour préserver l’équilibre entre biomes et régions habitées.',facts={'Biome':'Polaire','Localisation':'Extrême Nord','Caractéristique':'Toundra et glaces'},sections=[('Pôle climatique','La région se compose d’étendues enneigées et de terrains soumis à des conditions extrêmes. Elle est distincte des glaciers des hauts sommets, qui peuvent se trouver plus au sud.'),('Icebergs','Au large du Nord, quelques icebergs ponctuent les eaux froides, conformément à l’orientation cartographique choisie.'),('Échelle de la région','Les limites et la surface exacte de la zone restent à établir sur une carte de projection cohérente.')],related=['massif-nord','katoru','arelia'])
]
